import { Redis } from 'ioredis';
import { LRUCache } from 'lru-cache';

export interface RateLimitOptions {
  windowMs: number;
  maxRequests: number;
  keyPrefix?: string;
}

export interface RateLimitResult {
  allowed: boolean;
  limit: number;
  remaining: number;
  resetTimeMs: number;
  source: 'redis' | 'memory_fallback';
}

const LUA_TOKEN_BUCKET_SCRIPT = `
  local key = KEYS[1]
  local now = tonumber(ARGV[1])
  local windowMs = tonumber(ARGV[2])
  local maxReqs = tonumber(ARGV[3])
  local clearBefore = now - windowMs

  redis.call('ZREMRANGEBYSCORE', key, 0, clearBefore)
  local currentReqs = redis.call('ZCARD', key)

  if currentReqs < maxReqs then
    redis.call('ZADD', key, now, now)
    redis.call('PEXPIRE', key, windowMs)
    return {1, maxReqs - currentReqs - 1, now + windowMs}
  else
    local oldest = redis.call('ZRANGE', key, 0, 0, 'WITHSCORES')
    local resetMs = tonumber(oldest[2]) + windowMs
    return {0, 0, resetMs}
  end
`;

export class RateLimiter {
  private redis: Redis | null;
  private memoryCache: LRUCache<string, number[]>;
  private luaSha: string | null = null;

  constructor(redisClient?: Redis, private options: RateLimitOptions = { windowMs: 60000, maxRequests: 100 }) {
    this.redis = redisClient || null;
    this.memoryCache = new LRUCache<string, number[]>({
      max: 5000,
      ttl: options.windowMs,
    });
  }

  async checkLimit(identifier: string): Promise<RateLimitResult> {
    const key = `${this.options.keyPrefix || 'ratelimit'}:${identifier}`;
    const now = Date.now();

    if (this.redis && this.redis.status === 'ready') {
      try {
        const result = (await this.redis.eval(
          LUA_TOKEN_BUCKET_SCRIPT,
          1,
          key,
          now.toString(),
          this.options.windowMs.toString(),
          this.options.maxRequests.toString()
        )) as [number, number, number];

        return {
          allowed: result[0] === 1,
          limit: this.options.maxRequests,
          remaining: result[1],
          resetTimeMs: result[2],
          source: 'redis',
        };
      } catch (err) {
        console.warn('Redis rate limit check failed, falling back to local memory cache:', err);
      }
    }

    // Local memory fallback execution
    return this.checkMemoryFallback(key, now);
  }

  private checkMemoryFallback(key: string, now: number): RateLimitResult {
    const timestamps = this.memoryCache.get(key) || [];
    const validTimestamps = timestamps.filter((ts) => ts > now - this.options.windowMs);

    if (validTimestamps.length < this.options.maxRequests) {
      validTimestamps.push(now);
      this.memoryCache.set(key, validTimestamps);
      return {
        allowed: true,
        limit: this.options.maxRequests,
        remaining: this.options.maxRequests - validTimestamps.length,
        resetTimeMs: now + this.options.windowMs,
        source: 'memory_fallback',
      };
    }

    return {
      allowed: false,
      limit: this.options.maxRequests,
      remaining: 0,
      resetTimeMs: validTimestamps[0] + this.options.windowMs,
      source: 'memory_fallback',
    };
  }
}

