export class RateLimiter {
  constructor(private redis: Redis, private options: RateLimitOptions) {}

  async checkLimit(identifier: string) {
    const key = `ratelimit:${identifier}`;
    const now = Date.now();
    const clearBefore = now - this.options.windowMs;

    await this.redis.zremrangebyscore(key, 0, clearBefore);
    const current = await this.redis.zcard(key);

    if (current < this.options.maxRequests) {
      await this.redis.zadd(key, now, now);
      await this.redis.pexpire(key, this.options.windowMs);
      return { allowed: true, remaining: this.options.maxRequests - current - 1 };
    }
    return { allowed: false, remaining: 0 };
  }
}
